def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    row_lines = [r for r in range(h) if sum(v == 2 for v in grid[r]) >= w // 2]
    col_lines = [c for c in range(w) if sum(grid[r][c] == 2 for r in range(h)) >= h // 2]

    centers = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if grid[r][c] == 2 and all(
                grid[rr][cc] == 3
                for rr, cc in ((r-1, c), (r+1, c), (r, c-1), (r, c+1))
            ):
                centers.append((r, c))

    horizontal_rays = len(col_lines) >= len(row_lines)

    # The ray extends from each object's center, without covering existing colors.
    for r, c in centers:
        if horizontal_rays:
            for x in range(w):
                if out[r][x] == 0:
                    out[r][x] = 1
        else:
            for y in range(h):
                if out[y][c] == 0:
                    out[y][c] = 1

    # At crossings with other grid lines, add a 3-cell-wide perpendicular marker.
    for r, c in centers:
        if horizontal_rays:
            for x in col_lines:
                if x == c:
                    continue
                for rr in (r - 1, r + 1):
                    for cc in range(x - 1, x + 2):
                        if 0 <= rr < h and 0 <= cc < w:
                            out[rr][cc] = 1
                for cc in (x - 1, x + 1):
                    if 0 <= cc < w:
                        out[r][cc] = 1
        else:
            for y in row_lines:
                if y == r:
                    continue
                for rr in (y - 1, y + 1):
                    if 0 <= rr < h:
                        for cc in (c - 1, c + 1):
                            if 0 <= cc < w:
                                out[rr][cc] = 1
                for rr in (y - 1, y + 1):
                    if 0 <= rr < h:
                        out[rr][c] = 1
                for cc in (c - 1, c + 1):
                    if 0 <= cc < w:
                        out[y][cc] = 1

    return out
